        long fishHookSpawnCD = fishHookSpawnTimestamp + 1000;
        boolean hasFished = (currentTime < fishHookSpawnCD);

        if (hasFished && (lastWarned + (1000) < currentTime)) {
            getPlayer().sendMessage(LocaleLoader.getString("Fishing.Scared"));
